Since https://github.com/vitejs/vite/issues/5763#issuecomment-1974235806 no longer works and #17447 was closed and locked, here's another quick hack to disable the page refresh. Place this chicanery in your `package.json`. It works by commenting out `location.reload()` in vite's source code, and can survive through any npm reinstalls.
```
"scripts": {
	"start": "node -e \"require('fs');const file='node_modules/vite/dist/client/client.mjs';fs.writeFileSync(file,fs.readFileSync(file,'utf8').replace(/(?<!\\/\\/)(location\\.reload\\(\\))/g,'//\\$1'))\" && vite",
]
```

Vite has 3 .reload() calls as of v6.3.3 in various places (hmr error, websocket error, etc..)

 Use the following [pnpm patch](https://pnpm.io/cli/patch) to remove them all.

```patch
diff --git a/dist/client/client.mjs b/dist/client/client.mjs
index e395b722799b40047dc74a8fadb22a8ffc2219a7..e13843a2727475611c95b080467f45cb0ef6d822 100644
--- a/dist/client/client.mjs
+++ b/dist/client/client.mjs
@@ -872,7 +872,8 @@ const debounceReload = (time) => {
       timer = null;
     }
     timer = setTimeout(() => {
-      location.reload();
+      console.error('[vite] Reload Required');
+      // location.reload();
     }, time);
   };
 };
@@ -915,7 +916,8 @@ async function handleMessage(payload) {
       await hmrClient.notifyListeners("vite:beforeUpdate", payload);
       if (hasDocument) {
         if (isFirstUpdate && hasErrorOverlay()) {
-          location.reload();
+          console.error('[vite] Reload Required');
+          // location.reload();
           return;
         } else {
           if (enableOverlay) {
@@ -966,7 +968,8 @@ async function handleMessage(payload) {
           const url = new URL(socket.url);
           url.search = "";
           await waitForSuccessfulPing(url.href);
-          location.reload();
+          console.error('[vite] Reload Required');
+          // location.reload();
         }
       }
       break;

```

