As temporary solution while we w8 for something better. I (and my best firend chatGPT) created this function which put directly at postcss.config.js file. 

Also we originally implemented the plugin using the modern PostCSS 8 object API (postcssPlugin, Declaration()), but Vite silently skipped it because of how it loads plugins under ESM — the hook never executed.
Switching to the older function-style plugin format (root => {}) solved the issue immediately, because Vite always recognizes and runs that style regardless of module format or loader quirks.

Hope it will help someone. 


```
// postcss.config.js
import autoprefixer from 'autoprefixer';

function webpBackgroundPlugin() {
  return (root) => {
    root.walkDecls(/background(-image)?/, (decl) => {
      // Only handle png/jpg/jpeg
      const urlRegex = /url\((["']?)([^"')]+?\.(png|jpe?g))\1\)/i;
      const match = decl.value.match(urlRegex);
      if (!match) return;

      const originalUrl = match[2];
      const webpUrl = originalUrl.replace(/\.(png|jpe?g)$/i, '.webp');
      const rule = decl.parent;

      if (!rule || rule.type !== 'rule') return;

      // Clone rule, strip declarations, keep selector
      const newRule = rule.clone();
      newRule.removeAll();
      newRule.selector = `.webp ${rule.selector}`;

      newRule.append({
        prop: decl.prop,
        value: decl.value.replace(
          urlRegex,
          `url(${match[1]}${webpUrl}${match[1]})`
        ),
      });

      rule.after(newRule);
    });
  };
}

export default {
  plugins: [
    webpBackgroundPlugin(),
    autoprefixer(),
  ],
};

```

