I'll post my full plugin code here for future reference. What this plugin does is change `*.module.css` and `*.module.css?inline` imports so that they aren't automatically handled by Vite and instead are just plain strings and objects. This is so they can be used inside of a Web Component shadow root. (Vite's normal behavior is to inject styles in the document head which doesn't work with Shadow DOM.)

This is working as of vite 5.0.12 and hopefully will be useful for others in the future.

```ts
/* eslint-disable @typescript-eslint/explicit-function-return-type */
import { readFileSync } from "node:fs";
import { basename, dirname, join } from "node:path";
import { type Plugin, preprocessCSS, type ResolvedConfig } from "vite";
 
/**
 * This plugin basically does the same thing that Vite does by default, except it won't automatically emit the .css file and inject it into the document.
 */
export function cssModulesWCPlugin(): Plugin {
	let config: ResolvedConfig;
	return {
		name: "css-modules-wc",
		enforce: "pre",
		configResolved: (resolvedConfig) => {
			config = resolvedConfig;
		},
		resolveId: (id, importer) => {
			// Change the ID name so it doesn't get processed by the default CSS Vite plugin
			if (id.endsWith(".module.css")) {
				return join(dirname(importer!), `${basename(id)}.custom`);
			}
			if (id.endsWith(".module.css?inline")) {
				return join(dirname(importer!), `${basename(id).replace("?inline", "")}.custom?inline`);
			}
			return undefined;
		},
		load: async function (id) {
			if (id.includes(".module.css.custom")) {
				const isInline = id.includes("?inline");
				const fileName = id.replace(/\.custom.*$/, "");
				const { code, modules, deps } = await preprocessCSS(readFileSync(fileName, "utf-8"), fileName, config);
				this.addWatchFile(fileName);
				for (const depPath of deps ?? []) {
					this.addWatchFile(depPath);
				}
				if (isInline) {
					return `export default ${JSON.stringify(code)};`;
				}
				return `export default ${JSON.stringify(modules)};`;
			}
			return undefined;
		},
		handleHotUpdate: (context) => {
			const modulesToInvalidate = [...context.modules];
			if (context.file.endsWith(".module.css")) {
				const vmModule = context.server.moduleGraph.getModuleById(`${context.file}.custom`);
				if (vmModule !== undefined) {
					modulesToInvalidate.push(vmModule, ...vmModule.importers);
				}
				const vmInline = context.server.moduleGraph.getModuleById(`${context.file}.custom?inline`);
				if (vmInline !== undefined) {
					modulesToInvalidate.push(vmInline, ...vmInline.importers);
				}
			}
			return modulesToInvalidate;
		},
	};
}
```

