```js
    rollupOptions: {
      output: {
        manualChunks: (id) => {
          if (id.includes("node_modules")) {
            const parts = id.split("node_modules/");
            if (parts.length > 1 && parts[1].includes("react")) {
              return `react`;
            }
          }
        },
      },
    },
```

