A little cleaner way with one plugin, that removes only the `<link>`s to the CSS bundles generated by Vite:
```typescript
import type { Plugin } from 'vite';
import { defineConfig, HtmlTagDescriptor } from 'vite';

export default defineConfig({
  // ...
  plugins: [
    // ...
    injectCssAsStyleTag(),
    // ...
  ],
  // ...
});

function escapeRegex(string) {
  return string.replace(/[/\-\\^$*+?.()|[\]{}]/g, '\\$&');
}

function injectCssAsStyleTag(): Plugin {
  return {
    name: 'inject-css-as-style-tags',
    apply: 'build',
    transformIndexHtml: {
      order: 'post',
      handler: (html, ctx) => {
        const tags: HtmlTagDescriptor[] = [];
        const bundle = ctx.bundle;
        if (bundle == null) {
          return [];
        }

        Object.values(bundle)
          .filter((output) => output.fileName.endsWith('.css'))
          .forEach((output) => {
            if (output.type === 'asset' && typeof output.source === 'string') {
              tags.push({
                tag: 'style',
                children: output.source,
                injectTo: 'head',
              });
              const fileNameRegExp = RegExp(
                `<link.*href=".*${escapeRegex(output.fileName)}".*\\/?>`,
                'gmi',
              );
              html = html.replaceAll(fileNameRegExp, '');
            }
          });

        return { html, tags };
      },
    },
  };
}
```

