  ...,
  {
    name: 'noCache',
    configureServer(server) {
      server.middlewares.use((req, res, next) => {
        if (req.url?.includes('/my-module/')) {
          // Bypass vite's file cache - modifies ?v=... parameter
          req.url += Date.now()
          
