Edit: I've created a rollup plugin to rewrite the URL for now

Added to `build.rollupOptions.output.plugins: [ rewriteWorkerImport() ]`

```ts
const regex = /new Worker\(new URL\(\"(?<url>\.?\/.+?)\",\s?(?<base>self.location)\)/gm;
function rewriteWorkerImport() {
    return {
        name: 'rewriteWorkerImport',
        renderChunk: {
            order: 'post',
            async handler(code: string, chunk, outputOptions) {
                return code.replaceAll(regex, (match, url, _base) => {
                    if (url?.startsWith("/")) {
                        console.log(`Rewrite worker import in ${chunk.fileName}`);
                        // Make url file-relative
                        const newUrl = url.replace(/^\//, "");
                        return `new Worker(new URL("./${newUrl}", import.meta.url)`;
                    }
                    return match;
                });
            },
        }
    };
}
```

