	return {
		name: 'css-additional-data',
		enforce: 'pre',
		handleHotUpdate({ file, server }) {
			const tidyPath = path.replace(/^(\.\/|\.\.\/)+/, '')
			if (file.includes(tidyPath)) server.restart()
		},
