const injectEjs = ({source, destination, data}) => {
  name: "inject-ejs",
  createIndexHtml: {
    dependencies: [source],
    async create() {
      const template = await readFile(source, 'utf8')
      const html = await render(template, data, {
        async: true
      })
      await writeFile(destination, html)
      return destination
    }
  }
};

export default () => {
